package br.com.confirmacao.admin.api;import br.com.confirmacao.patient.api.PatientResponse;import br.com.confirmacao.patient.infrastructure.PatientRepository;import br.com.confirmacao.professional.api.ProfessionalResponse;import br.com.confirmacao.professional.infrastructure.ProfessionalRepository;import br.com.confirmacao.shared.api.PageResponse;import org.springdoc.core.annotations.ParameterObject;import org.springframework.data.domain.Pageable;import org.springframework.data.web.PageableDefault;import org.springframework.web.bind.annotation.*;@RestController@RequestMapping("/api/v1/admin")public class AdminDataController{private final ProfessionalRepository professionals;private final PatientRepository patients;public AdminDataController(ProfessionalRepository p,PatientRepository x){professionals=p;patients=x;}@GetMapping("/professionals")public PageResponse<ProfessionalResponse> professionals(@ParameterObject@PageableDefault(size=20,sort="fullName")Pageable p){return PageResponse.from(professionals.findAll(p).map(ProfessionalResponse::from));}@GetMapping("/patients")public PageResponse<PatientResponse> patients(@ParameterObject@PageableDefault(size=20,sort="fullName")Pageable p){return PageResponse.from(patients.findAll(p).map(PatientResponse::from));}}
